PRAGMA foreign_keys=ON;
BEGIN;
CREATE TABLE IF NOT EXISTS timing_audit_rules(id TEXT PRIMARY KEY,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS domain_timing_profiles(domain_id TEXT PRIMARY KEY REFERENCES domains(id),payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trigram_timing_periods(trigram TEXT PRIMARY KEY,payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS timing_audit_issues(id TEXT PRIMARY KEY,payload_json TEXT NOT NULL);
INSERT OR REPLACE INTO timing_audit_rules VALUES ('method-order','{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('numerical-method','{"id":"numerical-method","sectionId":"mh-058","quote":"后天则以卦数加时数，总之而分行卧坐立之迟速，以为事应之期。","application":"需后天原卦数、时数及占者动静；不是任何起卦法都取经卦数相加。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"后天则以卦数加时数，总之而分行卧坐立之迟速，以为事应之期。","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":377,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('horizon','{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('element-day-table','{"id":"element-day-table","sectionId":"mh-143","quote":"本日所属卦气如寅卯木、巳午火、申酉金、亥子水、辰戌丑未土也。","application":"五行日气表；和八卦时序表分别保存，不能互相替换。","evidence":{"sectionId":"mh-143","title":"日应","quote":"本日所属卦气如寅卯木、巳午火、申酉金、亥子水、辰戌丑未土也。","sourceRef":{"sourceId":"user-meihua","startChar":37834,"endChar":37923,"startLine":967,"endLine":969},"quoteOffsetInSection":57,"sectionSha256":"e795a1070cf6ea6add1b358b1210ef9e61df38603d58754c9db9c7aed338e7e9"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('phase-pace','{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('obstruction-duration','{"id":"obstruction-duration","sectionId":"mh-116","quote":"若乾克体，阻一日，兑克体，阻二日之类推之。","application":"在吉事有生扶又有克体的前提下论阻滞时长；不是起卦后第几日必败。多卦不可自行相加。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"若乾克体，阻一日，兑克体，阻二日之类推之。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":120,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('good-event','{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('adverse-event','{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('motion-number','{"id":"motion-number","sectionId":"mh-039","quote":"坐则事应迟，当倍其成卦之数而定之也。立则半迟半速，止以成卦之数定之可也。","application":"结合本段行取半；仍须明事理，不将数字候选当无条件期限。","evidence":{"sectionId":"mh-039","title":"老人有忧色占","quote":"坐则事应迟，当倍其成卦之数而定之也。立则半迟半速，止以成卦之数定之可也。","sourceRef":{"sourceId":"user-meihua","startChar":4812,"endChar":5156,"startLine":164,"endLine":167},"quoteOffsetInSection":262,"sectionSha256":"ebb1ab3f4a81fdefb98a49cf0a0d8d8c9a1d38a124dfac0ad516d559ce488e76"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('motion-exception','{"id":"motion-exception","sectionId":"mh-039","quote":"如占牡丹及观梅之类，则二日花皆朝夕之故，岂特成数之久也。","application":"问事朝夕急缓可限定应期；原数不能覆盖明确的当日或近日事理。","evidence":{"sectionId":"mh-039","title":"老人有忧色占","quote":"如占牡丹及观梅之类，则二日花皆朝夕之故，岂特成数之久也。","sourceRef":{"sourceId":"user-meihua","startChar":4812,"endChar":5156,"startLine":164,"endLine":167},"quoteOffsetInSection":308,"sectionSha256":"ebb1ab3f4a81fdefb98a49cf0a0d8d8c9a1d38a124dfac0ad516d559ce488e76"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('method-reproduction','{"id":"method-reproduction","sectionId":"mh-031","quote":"以物为上卦，方位为下卦，合物卦之数与方卦之数加时数以取动爻。","application":"原始输入必须复现原盘；不能为了凑天数增添未实际提供的取象。","evidence":{"sectionId":"mh-031","title":"物卦起例（端法后天起卦）","quote":"以物为上卦，方位为下卦，合物卦之数与方卦之数加时数以取动爻。","sourceRef":{"sourceId":"user-meihua","startChar":2672,"endChar":2724,"startLine":126,"endLine":128},"quoteOffsetInSection":20,"sectionSha256":"ca2cd65af2f060e706277c5aa7a76ba1b1e644a278dc2ba8d5ea80064b88e126"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('property-lifetime','{"id":"property-lifetime","sectionId":"mh-122","quote":"屋宅则以全卦之数刻其期。如屋宅之终应，盖屋宅有朽坏之期也。","application":"屋宅年数所指为朽坏，不是开工日、入住日或日常事务解决日。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"屋宅则以全卦之数刻其期。如屋宅之终应，盖屋宅有朽坏之期也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":178,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('marriage-scope','{"id":"marriage-scope","sectionId":"mh-122","quote":"然婚姻亦不过卜其吉凶，不必刻其期也。若吉凶之期，但以生体及比和之年月为吉期，克体之年月为不吉之期也。","application":"吉凶年月与婚成日期分开；不能为每个婚盘强填结婚日。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"然婚姻亦不过卜其吉凶，不必刻其期也。若吉凶之期，但以生体及比和之年月为吉期，克体之年月为不吉之期也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":261,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('burial-scope','{"id":"burial-scope","sectionId":"mh-122","quote":"坟墓亦有损坏，然占墓但占吉凶，不计成败也。","application":"不将吉地或不利之象编成某日安葬成功、失败或后代发财。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"坟墓亦有损坏，然占墓但占吉凶，不计成败也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":207,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('birth-date','{"id":"birth-date","sectionId":"mh-068","quote":"如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。","application":"生产日辰以用卦气数参时序，不套通用生体日期；产品仅作古籍研究展示。","evidence":{"sectionId":"mh-068","title":"生产占第六","quote":"如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。","sourceRef":{"sourceId":"user-meihua","startChar":16449,"endChar":16658,"startLine":542,"endLine":544},"quoteOffsetInSection":164,"sectionSha256":"4a549ef943b0ab9d5e00c08740661930a642d019e23300650cc1c45df0cb74cc"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('fame-date','{"id":"fame-date","sectionId":"mh-071","quote":"欲知名成之日，生体之卦气详之。","application":"名成之期，不等同于面试日或离职日。","evidence":{"sectionId":"mh-071","title":"求名占第九","quote":"欲知名成之日，生体之卦气详之。","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":82,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('fame-body-fallback','{"id":"fame-body-fallback","sectionId":"mh-071","quote":"若无克体之卦，则名易就，止看卦体时序之类，以定日期。","application":"限定无克体条件；不得省略条件后普遍改取体卦时序。","evidence":{"sectionId":"mh-071","title":"求名占第九","quote":"若无克体之卦，则名易就，止看卦体时序之类，以定日期。","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":112,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('fame-office-risk','{"id":"fame-office-risk","sectionId":"mh-071","quote":"其日期，看克体之卦气者，于八卦所属时序类中断之。","application":"本段针对在任者的官职风险；不直接套到所有求职者。","evidence":{"sectionId":"mh-071","title":"求名占第九","quote":"其日期，看克体之卦气者，于八卦所属时序类中断之。","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":179,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('wealth-gain','{"id":"wealth-gain","sectionId":"mh-072","quote":"欲知得财之日，生体之卦气定之。","application":"得财事件。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"欲知得财之日，生体之卦气定之。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":68,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('wealth-loss','{"id":"wealth-loss","sectionId":"mh-072","quote":"欲知破财之日，克体卦气定之。","application":"破财事件；无财可得不自动等于损失本金。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"欲知破财之日，克体卦气定之。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":83,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('wealth-control-gain','{"id":"wealth-control-gain","sectionId":"mh-072","quote":"又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。","application":"保留体克用与生体两类财应，不能只实现生体。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":98,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('wealth-drain-loss','{"id":"wealth-drain-loss","sectionId":"mh-072","quote":"若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。","application":"保留克体与泄体两类耗财应。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":128,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('traveler-return','{"id":"traveler-return","sectionId":"mh-122","quote":"又若问行人，以生体之日为归期，无生体比和之日，则归必迟。","application":"归来应期；不归、归迟本身不等于某个确定的终止日期。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"又若问行人，以生体之日为归期，无生体比和之日，则归必迟。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":688,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('health-periods','{"id":"health-periods","sectionId":"mh-078","quote":"若究和平之日，主卦决之。若详危厄之期，克体之卦定之。","application":"主卦一词保留，结合后文逢生案例；不擅改成唯一生体公式，不输出临床日期。","evidence":{"sectionId":"mh-078","title":"疾病占第十六","quote":"若究和平之日，主卦决之。若详危厄之期，克体之卦定之。","sourceRef":{"sourceId":"user-meihua","startChar":18034,"endChar":18923,"startLine":577,"endLine":582},"quoteOffsetInSection":156,"sectionSha256":"572657cf1f175fef0d8d5f11905a6029d2b216fa39de38b6fbf50704f42bdaa4"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('same-chart-not-same-story','{"id":"same-chart-not-same-story","sectionId":"mh-098","quote":"明日观梅得革，亦谓女子折花，可乎？","application":"同盘不允许直接移植古案人物、结局、时辰及反馈。","evidence":{"sectionId":"mh-098","title":"遗论","quote":"明日观梅得革，亦谓女子折花，可乎？","sourceRef":{"sourceId":"user-meihua","startChar":24107,"endChar":24402,"startLine":678,"endLine":680},"quoteOffsetInSection":212,"sectionSha256":"df441586910ddcc757064928abdd35cb3622429edb6391cbdf68b5b71e3e37e8"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('weather-relative','{"id":"weather-relative","sectionId":"mh-063","quote":"离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。","application":"天气有朝暮等专门时序，须天象背景；晴雨吉凶还取决于所求。","evidence":{"sectionId":"mh-063","title":"天时占第一","quote":"离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。","sourceRef":{"sourceId":"user-meihua","startChar":15052,"endChar":15857,"startLine":516,"endLine":519},"quoteOffsetInSection":701,"sectionSha256":"af077656352db7f70d2a8d6f5203d8b55a451f2d729e2a98fa007ef2453661f7"}}');
INSERT OR REPLACE INTO timing_audit_rules VALUES ('current-signs','{"id":"current-signs","sectionId":"mh-144","quote":"刻应者，即三要之诀也。占卜之顷，随所闻所见吉凶之兆以为吉凶之应。","application":"刻应指当下外应，不能把刻字解释为钟表分钟。","evidence":{"sectionId":"mh-144","title":"刻应","quote":"刻应者，即三要之诀也。占卜之顷，随所闻所见吉凶之兆以为吉凶之应。","sourceRef":{"sourceId":"user-meihua","startChar":37923,"endChar":37962,"startLine":970,"endLine":972},"quoteOffsetInSection":5,"sectionSha256":"ed446a83a81946cd653aac98d55bb5f7c38f82645ab946bfc8a13d1db608dd49"}}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-01','{"id":"domain-01","label":"天时","sectionId":"mh-063","mode":"weather-special","note":"先按三卦天象与四时、久晴久雨背景论朝暮变化；无固定通用天数。","eventLabels":{"body_controls_use":"晴雨变化","use_controls_body":"风雷变化","body_generates_use":"晴雨变化","use_generates_body":"晴雨变化","equal":"晴雨变化"},"directRuleIds":["weather-relative"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-063","title":"天时占第一","quote":"【天时占第一】\n凡占天时，不分体用，全观诸卦，详推五行。离多主晴，坎多主雨，坤乃陰晦，乾主晴明，震多则春夏雷轰，巽多则四时风烈，艮多则久雨必晴，兑多则不雨亦陰。夏占离多而无坎，则亢旱炎炎。冬占坎多而无离，则雨雪飘飘。\n全观诸卦者，谓互变卦。五行属离属火，主晴；坎为水，主雨；坤为地气，主陰；乾为天，主晴明；震为雷，巽为风，秋冬震多无制，亦有非常之雷，有巽佐之，则为风撼雷动之应；艮为山云之气，若雨久，得艮则当止。艮者，止也，亦土克水之义。兑为泽，故不雨亦陰。夫以造化之辨固难测，理数之妙亦可凭，是以乾象乎天，四时晴明；坤体乎地，一气惨然。乾、坤两同，晴雨时变。坤、艮两并，陰晦不常。卜数有陽有陰，卦象有奇有偶。陰雨陽晴，奇偶暗重。坤为老陰之极，久晴必雨；乾为老陽之极，久雨必晴。若逢重坎重离，亦日时晴时雨。坎为水，必雨；离为火，必晴。乾、兑为金，秋明晴；坎之水，冬雪凛冽；坤、艮之土，春雨泽，夏火炎蒸。《易》曰：“云从龙，风从虎”。又曰：“艮为云，巽为风。”艮、巽重逢，风云际会，飞沙走石，蔽日藏山，不以四时，不必二用。坎在艮上，布雾兴云，若在兑上，凝霜作雪。乾、兑为霜雪雹霰，离火为日电虹霓。离为电，震为雷，重会而雷电俱作。坎为雨，巽为风，相逢而风雨骤兴。震卦重逢，雷惊百里。坎爻叠见，润泽九垓。故卦体之两逢，亦爻象之总断。地天泰，水天需，昏蒙之象。天地否，水地比，黑暗之形。爻纯离，夏必旱，四季皆晴。爻纯坎，冬必寒，四时必雨。久雨不晴，逢艮必止。久晴不雨，得此亦然。又若水火既济、火水未济，四时不测风云；风泽中孚，泽风大过，三冬必然雨雪。水山蹇，山水蒙，百步必须执盖。地风升，风地观，四时不可行船。离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。巽、坎互离，虹霞乃见，巽、离互坎，造化亦同。又须推测四时，不可执迷一理。震、离为电、为雷，应在夏天，乾、兑为霜、为雪，验于冬月。天地之理大矣哉！得斯文者，当敬宝之。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":15052,"endChar":15857,"startLine":516,"endLine":519},"quoteOffsetInSection":0,"sectionSha256":"af077656352db7f70d2a8d6f5203d8b55a451f2d729e2a98fa007ef2453661f7"},"directRules":[{"id":"weather-relative","sectionId":"mh-063","quote":"离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。","application":"天气有朝暮等专门时序，须天象背景；晴雨吉凶还取决于所求。","evidence":{"sectionId":"mh-063","title":"天时占第一","quote":"离在艮上，暮雨朝晴，离互艮宫，暮晴朝雨。","sourceRef":{"sourceId":"user-meihua","startChar":15052,"endChar":15857,"startLine":516,"endLine":519},"quoteOffsetInSection":701,"sectionSha256":"af077656352db7f70d2a8d6f5203d8b55a451f2d729e2a98fa007ef2453661f7"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-02','{"id":"domain-02","label":"人事","sectionId":"mh-064","mode":"general","note":"参总诀，分别记成事、阻事、耗失；章内未另立固定日期公式。","eventLabels":{"body_controls_use":"事情可成","use_controls_body":"事情受阻或不成","body_generates_use":"耗失","use_generates_body":"事情进益","equal":"谋为顺遂"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-064","title":"人事占第二","quote":"【人事占第二】\n人事之占，详观体用。体卦为主，用卦为宾。用克体不宜，体克用则吉。用生体有进益之喜，体生用有耗失之患。体用比和，谋为吉利。更详观互卦、变卦，以断吉凶；复究盛衰，以明休咎。\n人事之占，则以全体用总章向决吉凶。若有生体之卦，即看前章八卦中生体之卦有何吉；又看克体之卦有何凶，即看前章克体之卦。无生克，止断本卦。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":15857,"endChar":16019,"startLine":520,"endLine":523},"quoteOffsetInSection":0,"sectionSha256":"bd38cba2a930ead17790ce71be9564bcf90c903b3d1b92fd6c311a48c93fefcd"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-03','{"id":"domain-03","label":"家宅","sectionId":"mh-065","mode":"general-property","note":"日常家宅事务与屋宅寿限分开；屋宅案例另列，不套到所有家庭问题。","eventLabels":{"body_controls_use":"家宅多吉","use_controls_body":"家宅不宁","body_generates_use":"家宅耗散","use_generates_body":"家宅进益","equal":"家宅安稳"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-065","title":"家宅占第三","quote":"【家宅占第三】\n凡占家宅，以体为主，用为家宅。体克用，则家宅多吉，用克体，则家宅多凶。体生用，多耗散，或防失盗之忧。用生体，多进益，或有馈送之喜。体用比和，家宅安稳。如有生体之卦，即以前章人事占断之。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16019,"endChar":16121,"startLine":524,"endLine":526},"quoteOffsetInSection":0,"sectionSha256":"3029db525ec03cab7a393edcfe2a2731bbadf44a71a55476741babaf458a4248"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-04','{"id":"domain-04","label":"屋舍","sectionId":"mh-066","mode":"property","note":"新建、居住吉凶、朽坏是不同应事；长久寿限另按原数与事理。","eventLabels":{"body_controls_use":"居住吉利","use_controls_body":"居住不利","body_generates_use":"资财衰退","use_generates_body":"门户兴隆","equal":"住居安稳"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-066","title":"屋舍占第四","quote":"【屋舍占第四】\n凡占屋舍，以体为主，用为屋舍。体克用，居之吉，用克体，居之凶。体生用，主资财衰退；用生体，则门户兴隆。体用比和，自然安稳。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16121,"endChar":16192,"startLine":527,"endLine":529},"quoteOffsetInSection":0,"sectionSha256":"3e6ecd42d6bf267c92bcaff5a06dea6b282de0190b483bbedaae09592fcf8cb3"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-05','{"id":"domain-05","label":"婚姻","sectionId":"mh-067","mode":"marriage","note":"总诀以吉凶年月为主，不强刻每盘成婚日；具体古案数期保持个案条件。","eventLabels":{"body_controls_use":"婚可成但迟","use_controls_body":"婚不可成","body_generates_use":"婚难成或有失","use_generates_body":"婚易成或有得","equal":"婚姻吉利"},"directRuleIds":["marriage-scope"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-067","title":"婚姻占第五","quote":"【婚姻占第五】\n占婚姻以体为主，用为婚姻。用生体，婚易成，或因婚有得；体生用，婚难成，或因婚有失。体克用，可成但成之迟；用克体，不可成，成亦有害。体用比和，婚姻吉利。\n占婚，体为所占之家，用为所婚之家。体卦旺，则此家门户胜；用卦旺，则彼家资盛。生体，则得婚姻之财；或彼有相就之意；体生，则无嫁奁之资，或此去求婚方谐。若体用比和，则彼此相就，良配无疑。\n乾：端正而长\n坎：邪婬、黑色、嫉妒、奢侈\n艮：色黄多巧\n震：美貌难犯\n巽：发少稀疏，丑陋心贪\n离：短赤色，性不常\n坤：貌丑，大腹而黄\n兑：高长，语话喜悦，白色\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16192,"endChar":16449,"startLine":530,"endLine":541},"quoteOffsetInSection":0,"sectionSha256":"35529480187dd37f03bbba98a2d71b5cce2e6a02229e0376efde3aac01c68c10"},"directRules":[{"id":"marriage-scope","sectionId":"mh-122","quote":"然婚姻亦不过卜其吉凶，不必刻其期也。若吉凶之期，但以生体及比和之年月为吉期，克体之年月为不吉之期也。","application":"吉凶年月与婚成日期分开；不能为每个婚盘强填结婚日。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"然婚姻亦不过卜其吉凶，不必刻其期也。若吉凶之期，但以生体及比和之年月为吉期，克体之年月为不吉之期也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":261,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-06','{"id":"domain-06","label":"生产","sectionId":"mh-068","mode":"birth-reference","note":"专条以用卦气数参八卦时序；保留古籍研究，不输出真实分娩或安危日期。","eventLabels":{"body_controls_use":"原典子方受制","use_controls_body":"原典母方受制","body_generates_use":"原典利子","use_generates_body":"原典利母","equal":"原典生育顺快"},"directRuleIds":["birth-date"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":true,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-068","title":"生产占第六","quote":"【生产占第六】\n占生产，以体为母，用为生。体用俱宜乘旺，不宜乘衰。宜相生，不宜相克。体克用不利于子；用克体不利于母。体克用而用卦衰，则子难完；用克体而体卦衰，则母难保。用生体，利于母；体生用，利于子。体用比和，生育顺快。若欲辨其男女，当于前卦审之。陽卦陽爻多者则生男，陰卦陰爻多者生女。陰陽卦爻相生，则察所占左右人之奇偶以证之。如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16449,"endChar":16658,"startLine":542,"endLine":544},"quoteOffsetInSection":0,"sectionSha256":"4a549ef943b0ab9d5e00c08740661930a642d019e23300650cc1c45df0cb74cc"},"directRules":[{"id":"birth-date","sectionId":"mh-068","quote":"如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。","application":"生产日辰以用卦气数参时序，不套通用生体日期；产品仅作古籍研究展示。","evidence":{"sectionId":"mh-068","title":"生产占第六","quote":"如欲决其日辰，则以用卦之气数参决之。所谓卦之气数者，即看何为用卦，于八卦时序之类次之。","sourceRef":{"sourceId":"user-meihua","startChar":16449,"endChar":16658,"startLine":542,"endLine":544},"quoteOffsetInSection":164,"sectionSha256":"4a549ef943b0ab9d5e00c08740661930a642d019e23300650cc1c45df0cb74cc"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-07','{"id":"domain-07","label":"饮食","sectionId":"mh-069","mode":"general","note":"须保留今日、今夕等问题限定；今日动静案例不能因总数十三改成十三日后赴宴。","eventLabels":{"body_controls_use":"饮食有阻","use_controls_body":"饮食无成","body_generates_use":"饮食难就","use_generates_body":"饮食丰足","equal":"饮食丰足"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-069","title":"饮食占第七","quote":"【饮食占第七】\n凡占饮食，以体为主，用为饮食。用生体，饮食必丰；体生用，饮食难就。体克用，则饮食有阻；用克体，饮食必无。体用比和，饮食丰足。又卦中有坎则有酒，有兑则有食。无坎无兑，则皆无。兑、坎生体，酒肉醉饱。欲知所食何物，以饮食推之。欲知席上何人，以互卦人事推之。\n饮食人事类者，即前八卦内万物属类是也。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16658,"endChar":16813,"startLine":545,"endLine":548},"quoteOffsetInSection":0,"sectionSha256":"5325857ef12ef65149fcdf67a3f804acea786d0c970cf017a3ac6eab754bd9ce"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-08','{"id":"domain-08","label":"求谋","sectionId":"mh-070","mode":"general","note":"体克用的迟没有固定天数；参总诀的生扶阶段、克体阻期。","eventLabels":{"body_controls_use":"谋可成但迟","use_controls_body":"求谋不成","body_generates_use":"多谋少遂","use_generates_body":"不谋而成","equal":"求谋称意"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-070","title":"求谋占第八","quote":"【求谋占第八】\n占求谋，以体为主，用为所谋之事。体克用，谋虽可成，但成迟。用克体，求谋不成，谋亦有害。用生体。不谋而成；体生用，多谋少遂。体用比和，求谋称意。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16813,"endChar":16894,"startLine":549,"endLine":551},"quoteOffsetInSection":0,"sectionSha256":"fdb5ca7bac9d4dde8b94fcde889a62b3685732573d8028376883d137e3f08993"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-09','{"id":"domain-09","label":"求名","sectionId":"mh-071","mode":"fame","note":"名成用生体气；无克体才可参体卦时序；在任受责另取克体气。","eventLabels":{"body_controls_use":"名可成但迟","use_controls_body":"名不可成","body_generates_use":"名不可就或有丧","use_generates_body":"名易成或有得","equal":"功名称意"},"directRuleIds":["fame-date","fame-body-fallback","fame-office-risk"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-071","title":"求名占第九","quote":"【求名占第九】\n凡占求名，以体为主，用为名。体克用，名可成，但成迟。用克体，名不可成。体生用，名不可就，或因名有丧。用生体，名易成，或因名有得。体用比和，功名称意。欲知名成之日，生体之卦气详之。欲知职任之处，变卦之方道决之。若无克体之卦，则名易就，止看卦体时序之类，以定日期。若在任占卜，最忌见克体之卦，如卦有克体者，即居官见祸，轻则上司责罚，重则削官退居。其日期，看克体之卦气者，于八卦所属时序类中断之。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":0,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"},"directRules":[{"id":"fame-date","sectionId":"mh-071","quote":"欲知名成之日，生体之卦气详之。","application":"名成之期，不等同于面试日或离职日。","evidence":{"sectionId":"mh-071","title":"求名占第九","quote":"欲知名成之日，生体之卦气详之。","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":82,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"}},{"id":"fame-body-fallback","sectionId":"mh-071","quote":"若无克体之卦，则名易就，止看卦体时序之类，以定日期。","application":"限定无克体条件；不得省略条件后普遍改取体卦时序。","evidence":{"sectionId":"mh-071","title":"求名占第九","quote":"若无克体之卦，则名易就，止看卦体时序之类，以定日期。","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":112,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"}},{"id":"fame-office-risk","sectionId":"mh-071","quote":"其日期，看克体之卦气者，于八卦所属时序类中断之。","application":"本段针对在任者的官职风险；不直接套到所有求职者。","evidence":{"sectionId":"mh-071","title":"求名占第九","quote":"其日期，看克体之卦气者，于八卦所属时序类中断之。","sourceRef":{"sourceId":"user-meihua","startChar":16894,"endChar":17099,"startLine":552,"endLine":554},"quoteOffsetInSection":179,"sectionSha256":"e9537fdcffd069df20f98fbfbc743c051ccbb8eaf857631047ed201ed5cd0d77"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-10','{"id":"domain-10","label":"求财","sectionId":"mh-072","mode":"wealth","note":"得财与破财各有专条；不成、无财、破财三个事件不能互换。","eventLabels":{"body_controls_use":"得财","use_controls_body":"无财可得","body_generates_use":"财有耗损","use_generates_body":"财有进益","equal":"财利顺遂"},"directRuleIds":["wealth-gain","wealth-loss","wealth-control-gain","wealth-drain-loss"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-072","title":"求财占第十","quote":"【求财占第十】\n占求财，以体为主，以用为财。体克用，有财；用克体，无财。体生用，财有损耗之忧；用生体，财有进益之喜。体用比和，财利快意。欲知得财之日，生体之卦气定之。欲知破财之日，克体卦气定之。\n又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":0,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"},"directRules":[{"id":"wealth-gain","sectionId":"mh-072","quote":"欲知得财之日，生体之卦气定之。","application":"得财事件。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"欲知得财之日，生体之卦气定之。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":68,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}},{"id":"wealth-loss","sectionId":"mh-072","quote":"欲知破财之日，克体卦气定之。","application":"破财事件；无财可得不自动等于损失本金。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"欲知破财之日，克体卦气定之。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":83,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}},{"id":"wealth-control-gain","sectionId":"mh-072","quote":"又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。","application":"保留体克用与生体两类财应，不能只实现生体。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"又若卦中有体克用之卦，及生体之卦，则有财，此卦气即见财之日。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":98,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}},{"id":"wealth-drain-loss","sectionId":"mh-072","quote":"若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。","application":"保留克体与泄体两类耗财应。","evidence":{"sectionId":"mh-072","title":"求财占第十","quote":"若卦中有克体之卦，及体生用之卦，即破财，此卦气破财之日。","sourceRef":{"sourceId":"user-meihua","startChar":17099,"endChar":17257,"startLine":555,"endLine":558},"quoteOffsetInSection":128,"sectionSha256":"4aee789125c7a0be6e0ae0a9011ce4682376226ff569ddab0cc585ee7ec5d0ac"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-11','{"id":"domain-11","label":"交易","sectionId":"mh-073","mode":"general","note":"本章判成败与得失，具体取期参总诀；不把交易不成自动写成被骗或破财。","eventLabels":{"body_controls_use":"成交有财","use_controls_body":"交易不成","body_generates_use":"交易难成或有损","use_generates_body":"成交有财","equal":"易于成交"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-073","title":"交易占第十一","quote":"【交易占第十一】\n占交易，以体为主，用为财。体克用，有财；用克体，不成。体生用，难成，或因交易有失。用生体，即成，成必有财。体用比和，易成。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":17257,"endChar":17329,"startLine":559,"endLine":561},"quoteOffsetInSection":0,"sectionSha256":"a5cec4d584ba7766d0b29714cd77e9979c58168479b8259ac4d79d1ff2b22eb1"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-12','{"id":"domain-12","label":"出行","sectionId":"mh-074","mode":"general","note":"所行吉凶、出发时点、归来时点分开，原条没有一见生体便指定出发日期的公式。","eventLabels":{"body_controls_use":"所行得意","use_controls_body":"出行不利","body_generates_use":"出行破耗","use_generates_body":"出行有所得","equal":"出行顺快"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-074","title":"出行占第十二","quote":"【出行占第十二】\n占出行，以体为主，用为所行之应。体克用，可行，所至多得意。用克体，出则有祸。体生用，出行有破耗之失；用生体，有意外之财。体用比和，出行顺快。\n又凡出行，体宜乘旺，诸卦宜生体。体卦乾、震多，主动。坤、艮多，不动。巽宜舟行，离宜陆行。坎妨失脱，兑主纷争。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":17329,"endChar":17465,"startLine":562,"endLine":565},"quoteOffsetInSection":0,"sectionSha256":"ced92e691087ece2c91cfc2732a577983c400cf4ff322924962227ebf9ce6dcc"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-13','{"id":"domain-13","label":"行人","sectionId":"mh-075","mode":"traveler","note":"生体日为归期，无生体比和则迟；不归不能变造为某日确定失联。","eventLabels":{"body_controls_use":"行人归迟","use_controls_body":"行人不归","body_generates_use":"行人未归","use_generates_body":"行人归来","equal":"归期较近"},"directRuleIds":["traveler-return"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-075","title":"行人占第十三","quote":"【行人占第十三】\n占行人，以体为主，用为行人。体克用，行人归迟；用克体，行人不归。体生用，行人未归；用生体，行人即归。体用比和，归期不日矣。\n又以用卦看行人在外之情况。逢生，在外顺快；逢衰受克，在外灾殃。震多不宁，艮多有阻。坎有险难，兑主纷争。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":17465,"endChar":17589,"startLine":566,"endLine":569},"quoteOffsetInSection":0,"sectionSha256":"58bf3c6769a65e63d95f54d332c731e1ec84e995124a00d0646339066ccd147f"},"directRules":[{"id":"traveler-return","sectionId":"mh-122","quote":"又若问行人，以生体之日为归期，无生体比和之日，则归必迟。","application":"归来应期；不归、归迟本身不等于某个确定的终止日期。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"又若问行人，以生体之日为归期，无生体比和之日，则归必迟。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":688,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-14','{"id":"domain-14","label":"谒见","sectionId":"mh-076","mode":"general","note":"章内无另立定日公式；参总诀并区分相见与见后得益。","eventLabels":{"body_controls_use":"可相见","use_controls_body":"不能相见","body_generates_use":"难见或见而无益","use_generates_body":"相见有得","equal":"欢然相见"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-076","title":"谒见占第十四","quote":"【谒见占第十四】\n占谒见，以体为主，用为所见之人。体克用，可见；用克体，不见。体生用，难见，见之而无益；用生体，可见，见之且有得。体用比和，欢然相见。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":17589,"endChar":17666,"startLine":570,"endLine":572},"quoteOffsetInSection":0,"sectionSha256":"7210f4d536e5096d9e3e6b4093100cccbef50f8322088b5803b56aed8a19c15d"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-15','{"id":"domain-15","label":"失物","sectionId":"mh-077","mode":"general","note":"方位是寻物处所，不是日期；物难见不能扩大成某天永久丢失。","eventLabels":{"body_controls_use":"可寻迟得","use_controls_body":"不可寻","body_generates_use":"物难见","use_generates_body":"物易寻","equal":"物不失"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-077","title":"失物占第十五","quote":"【失物占第十五】\n占失物，以体为主，用为失物。体克用，可寻迟得；用克体，不可寻。体生用，物难见；用生体，物易寻。体用比和，物不失矣。\n又以变卦为失物之所在。如变是乾，则觅于西北或公榭楼阁之所，或金石之傍，或圆器之中，或高亢之地。变卦是坤，则觅于西南方，或田野之所，或仓禀之处，或稼穑之处，或土窖穴藏之所，或瓦器方器之中。震则寻于东方，或山林之所，或丛棘之内，钟鼓之傍，或闹市之地，或大途之所。巽则寻于东南方，或山林之所，或寺观之地，或菜蔬之园，或舟居之间，或木器之内。坎则寻于北方，多藏于水边或溪井沟渠之处，或酒醋之边，或鱼盐之地。离则寻于南方，或疱厨之间，或炉冶之傍，或在明窗，或遗虚室，或在文书之侧，或在烟火之地。艮则寻于东北方，或山林之内，或近路边，或岩石傍，或藏土穴。兑则寻于西方，或居泽畔，或败垣破壁之内，或废井缺沼之中。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":17666,"endChar":18034,"startLine":573,"endLine":576},"quoteOffsetInSection":0,"sectionSha256":"5afbebcea890ac4ea725615a0c82c6389a9f9942f426095cbd525dd2ae1b14fe"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-16','{"id":"domain-16","label":"疾病","sectionId":"mh-078","mode":"health-reference","note":"区分和平与危厄的原文取期；保留主卦异义及矛盾案例，禁止生死、疗效、停药日期输出。","eventLabels":{"body_controls_use":"原典病易安","use_controls_body":"原典病受制","body_generates_use":"原典迁延难好","use_generates_body":"原典逢生","equal":"原典疾病易安"},"directRuleIds":["health-periods"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":true,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-078","title":"疾病占第十六","quote":"【疾病占第十六】\n凡占疾病，以体为病人，用为病症。体卦宜旺不宜衰，体宜逢生，不宜见克。用宜生体，不宜克体。体克用，病易安；体生用，病难愈。体克用者，勿药有喜；用克体者，虽药无功。若体逢克而乘旺，犹为庶几。体遇克而更衰，断无存日。欲知凶中有救，生体之卦存焉。体生用者，迁延难好；用生体者，即愈。体用比和，疾病易安。若究和平之日，主卦决之。若详危厄之期，克体之卦定之。若论医药之属，当看生体之卦。如离卦生体，宜服热药；坎卦生体，宜服冷药，如艮温补；乾、兑凉药是也。\n又有信鬼神之说，虽非《易》道，然不可谓《易》道之不该。姑以理推之。如卦有克体者，即可测其鬼神。乾卦克体，主有西北方之神，或兵刀之鬼，或天行时气，或乘正之邪神。坤则西南之神，或旷野之鬼，或连亲之鬼，或水土里社之神，或犯方隅，或无主之祟。震则东方之神，或木下之神，或妖怪百端，或影响时见。巽则东南之鬼，或自缢戕生，或枷锁致命。坎则北方之鬼，或水旁之神，或没溺而亡，或血疾之鬼。离则南方之鬼，或猛勇之神，或犯灶司，或得衍于香火，或焚烧之鬼。或遇热病而亡。艮则东北之神，或是山林之祟，或山魈木客，或土怪石精。兑则西方之神，或阵亡之鬼，或废疾之鬼，或刎颈戕生之鬼。卦中无克体之卦者，不必论之。\n又问乾上坤下，占病如何断，尧夫曰：“乾上坤下第一爻动，便是生体之义。变为震木，互见巽艮，俱是生成之义，是谓不灾，逢生之日即愈。”\n又问：“第二爻动如何？”曰：“是变为坎水，乃泄体败金之义。金入水乡，互见巽、离，乃为风火扇炉，俱为克体之义。更看占时外应如何，即为焚尸之象，断之死无疑矣。以春夏秋冬四季推之，更见详理。”又曰：“第三爻动，坤变艮土，俱在生体之义，不问互卦，亦断其吉无疑。”又曰：“第四爻动，乾变巽木，金木俱有克体之义，互吉亦凶。木有扛尸之义，金为砖椁之推。是必定之推，必定之理。”又曰：“第五爻动，乾变离，反能生体，互变俱生体，是其吉无疑。更有吉兆则愈吉。其断明矣。”又曰：“第六爻动，乾变兑，则能泄体，互见巽、艮，一凶一吉，其病非死必危。亦宜看兆吉凶，吉则言吉，凶则言凶。此断甚明。余卦皆仿此断，则心易无不验矣。”\n\n","sourceRef":{"sourceId":"user-meihua","startChar":18034,"endChar":18923,"startLine":577,"endLine":582},"quoteOffsetInSection":0,"sectionSha256":"572657cf1f175fef0d8d5f11905a6029d2b216fa39de38b6fbf50704f42bdaa4"},"directRules":[{"id":"health-periods","sectionId":"mh-078","quote":"若究和平之日，主卦决之。若详危厄之期，克体之卦定之。","application":"主卦一词保留，结合后文逢生案例；不擅改成唯一生体公式，不输出临床日期。","evidence":{"sectionId":"mh-078","title":"疾病占第十六","quote":"若究和平之日，主卦决之。若详危厄之期，克体之卦定之。","sourceRef":{"sourceId":"user-meihua","startChar":18034,"endChar":18923,"startLine":577,"endLine":582},"quoteOffsetInSection":156,"sectionSha256":"572657cf1f175fef0d8d5f11905a6029d2b216fa39de38b6fbf50704f42bdaa4"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-17','{"id":"domain-17","label":"官讼","sectionId":"mh-079","mode":"general","note":"判输赢、损耗与调和是不同事件；不能把卦气直接当法院开庭或宣判日期。","eventLabels":{"body_controls_use":"自己一方占优","use_controls_body":"对方占优","body_generates_use":"因讼耗失","use_generates_body":"因讼有得","equal":"调和解争"},"directRuleIds":[],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":false,"source":{"sectionId":"mh-079","title":"官讼占第十七","quote":"【官讼占第十七】\n占官讼，以体为主，用为对辞之人与官讼之应。体卦宜旺，用卦宜衰。体宜用生，不宜生用。宜生体，不宜克体。是故体克用者，已胜人；用克体者，人胜己。体生用，非为失理，或因官有所丧；用生体，不止得理，或因讼有所得。体用比和，官讼最吉。非但扶持之力，必有主和之义。\n\n","sourceRef":{"sourceId":"user-meihua","startChar":18923,"endChar":19060,"startLine":583,"endLine":585},"quoteOffsetInSection":0,"sectionSha256":"dfd86319448a8a6b61ed2938156359484375a6de3181a36cddf7949a47cf7f6e"},"directRules":[],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
INSERT OR REPLACE INTO domain_timing_profiles VALUES ('domain-18','{"id":"domain-18","label":"坟墓","sectionId":"mh-080","mode":"burial","note":"依原文只论吉凶，不硬填成功失败之日；后嗣荫益保留为文献说法。","eventLabels":{"body_controls_use":"葬之吉","use_controls_body":"葬之凶","body_generates_use":"原典主运退","use_generates_body":"原典主兴隆","equal":"吉地"},"directRuleIds":["burial-scope"],"generalRuleIds":["method-order","horizon","good-event","adverse-event","phase-pace"],"clinicalReferenceOnly":false,"noAutomaticCompletionDate":true,"source":{"sectionId":"mh-080","title":"坟墓占第十八","quote":"【坟墓占第十八】\n占坟墓以体为主，用为坟墓。体克用，葬之吉；用克体，葬之凶。体生用，葬之主运退；用生体，葬之主兴隆，有荫益后嗣。体用比和，乃为吉地。大宜葬，葬之吉昌。\n上为用体之诀，始发十八章占例，以示后学之法则。然庶务之多，岂止十八占而已乎！然此十八占，乃大事之切要者，占者以类而推之可也。\n\n\n","sourceRef":{"sourceId":"user-meihua","startChar":19060,"endChar":19209,"startLine":586,"endLine":590},"quoteOffsetInSection":0,"sectionSha256":"a9200e01390edd163658ffff34729ef09e5141019ed80535ffbb0b0fe00c37d1"},"directRules":[{"id":"burial-scope","sectionId":"mh-122","quote":"坟墓亦有损坏，然占墓但占吉凶，不计成败也。","application":"不将吉地或不利之象编成某日安葬成功、失败或后代发财。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"坟墓亦有损坏，然占墓但占吉凶，不计成败也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":207,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}}],"generalRules":[{"id":"method-order","sectionId":"mh-058","quote":"先天之卦，定事应之期，则取之卦气","application":"先定起卦方法；先天气期与后天数期分开，不凭盘形倒造原数。","evidence":{"sectionId":"mh-058","title":"先天后天论","quote":"先天之卦，定事应之期，则取之卦气","sourceRef":{"sourceId":"user-meihua","startChar":12631,"endChar":13158,"startLine":483,"endLine":485},"quoteOffsetInSection":301,"sectionSha256":"9445465c90afd818ec0dc6a9aa545b9d51a6457a5421e74c039b31a280687cc9"}},{"id":"horizon","sectionId":"mh-122","quote":"应之期远，则以年，近则以月，又近则以日也。","application":"时间单位按所问远近确定；不从地支名称自动决定单位或轮次。","evidence":{"sectionId":"mh-122","title":"占卜克应之诀","quote":"应之期远，则以年，近则以月，又近则以日也。","sourceRef":{"sourceId":"user-meihua","startChar":31207,"endChar":31941,"startLine":822,"endLine":825},"quoteOffsetInSection":567,"sectionSha256":"03b22c48b5987e56215e771960344ab27858da53e46aad51c9f661086f4e1102"}},{"id":"good-event","sectionId":"mh-116","quote":"看卦中有生体之卦，则事应于生体卦气之日","application":"一般吉事取期依据；具体应何事，仍由相应门类的条文限定。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"看卦中有生体之卦，则事应于生体卦气之日","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":222,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"adverse-event","sectionId":"mh-116","quote":"有克体之卦，则事败于克体卦气之日。","application":"凶应也有取期；受阻、不成、破财等事件必须分别命名。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"有克体之卦，则事败于克体卦气之日。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":242,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}},{"id":"phase-pace","sectionId":"mh-116","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","application":"即、渐、稍迟是相对进程，不等于一、二、三天。","evidence":{"sectionId":"mh-116","title":"占卦诀","quote":"如生体是用卦，则事即成。生体是互卦，则渐成。生体是变卦，则稍迟耳。","sourceRef":{"sourceId":"user-meihua","startChar":29155,"endChar":29424,"startLine":791,"endLine":794},"quoteOffsetInSection":50,"sectionSha256":"4ac8d184016239aae042fa48c68e0c4daa1dac17773b5f7b527312c2a35c0dfb"}}]}');
