INSERT OR REPLACE INTO timing_audit_issues VALUES ('TIMING_QIAN_KUN_VARIANT','{"id":"TIMING_QIAN_KUN_VARIANT","sectionIds":["mh-058","mh-052"],"status":"unresolved","description":"先天后天论原载“或坤为戌、亥之日时”，与八卦时序坤未申、乾戌亥不合。疑为乾字，但对校本同载此文，不能无纸本证据改作定论。该短句不用于自动映射。"}');
INSERT OR REPLACE INTO timing_audit_issues VALUES ('PROPERTY_TOTALS_NOT_UNIFIED','{"id":"PROPERTY_TOTALS_NOT_UNIFIED","sectionIds":["mh-108","mh-109"],"status":"unresolved","description":"按起卦加数例保留的输入复加，田29、王27、韩44；屋宅断寿限却载29、22、31。不可把22、31当统一求和公式的验算通过值。"}');
INSERT OR REPLACE INTO timing_audit_issues VALUES ('HEALTH_MAIN_TRIGRAM_TERM','{"id":"HEALTH_MAIN_TRIGRAM_TERM","sectionIds":["mh-078"],"status":"unresolved","description":"和平之日的“主卦”未在本句消歧；且后列天地否各爻示例有结构矛盾。原文保留，不能自动替换为唯一体卦或生体卦日期算法。"}');
INSERT OR REPLACE INTO timing_audit_issues VALUES ('DELAY_IS_NOT_EVENT_DATE','{"id":"DELAY_IS_NOT_EVENT_DATE","sectionIds":["mh-116"],"status":"scoped","description":"乾阻一日、兑阻二日表示在相应前提下的阻滞时长，不能改成第1日或第2日一定失败。"}');
INSERT OR REPLACE INTO timing_audit_issues VALUES ('CASE_MIXED_MUTUAL_RELATIONS','{"id":"CASE_MIXED_MUTUAL_RELATIONS","sectionIds":["mh-040","mh-041"],"status":"scoped","description":"少年案互震生离、坎克离；牛案互坤比和、震克坤。原文互变俱生或俱克不能当成所有节点同向的结构事实。"}');
INSERT OR REPLACE INTO timing_audit_issues VALUES ('VOID_RULES_ARE_USER_EXTENSION','{"id":"VOID_RULES_ARE_USER_EXTENSION","sectionIds":[],"status":"source-separated","description":"旬空、真空、填冲合属于用户另给扩展；本次三卷未检出旬空/空亡专条。保留为独立规则层，不能冒称全是古籍原文。"}');
INSERT OR REPLACE INTO timing_audit_issues VALUES ('CALENDAR_OCCURRENCE_NOT_FORECAST_SELECTION','{"id":"CALENDAR_OCCURRENCE_NOT_FORECAST_SELECTION","sectionIds":["mh-122"],"status":"software-boundary","description":"下一次某支日距离起卦几天只是历法候选；原书没有无条件选择下一轮或只选最近两天的规定。"}');
